import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { jwtDecode } from 'jwt-decode';// Ensure you import jwtDecode correctly
import './AddProduct.css';

const AddProduct = () => {
  const [product, setProduct] = useState({
    name: '',
    price: '',
    quantity: '',
    description: '',
    listingDate: '',
    user_id: '',
  });
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');

  useEffect(() => {
    const token = localStorage.getItem('token');
    if (token) {
      try {
        const decodedToken = jwtDecode(token);
        console.log('Decoded token:', decodedToken);
        const userId = decodedToken.id; // Ensure the field exists
        setProduct((prevProduct) => ({
          ...prevProduct,
          user_id: userId,
        }));
        setIsLoggedIn(true);
      } catch (error) {
        console.error('Error decoding token:', error);
        setErrorMessage('Invalid token. Please log in again.');
        setIsLoggedIn(false);
      }
    } else {
      setErrorMessage('No token found. Please log in.');
    }
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setProduct({
      ...product,
      [name]: value,
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!product.user_id) {
      alert('Please provide a valid user ID.');
      return;
    }

    try {
      await axios.post(
        'http://localhost:8080/api/products',
        {
          name: product.name,
          price: product.price,
          quantity: product.quantity,
          description: product.description,
          listingDate: product.listingDate,
          user: { id: product.user_id }, // Corrected 'use' to 'user'
        },
        {
          headers: { 'Content-Type': 'application/json' },
        }
      );

      alert('Product added successfully!');
      setProduct((prevProduct) => ({
        ...prevProduct,
        name: '',
        price: '',
        quantity: '',
        description: '',
        listingDate: '',
      }));
    } catch (error) {
      console.error('Error adding product:', error);
      alert('Failed to add product.');
    }
  };

  return (
    <div className="add-product-container">
      <h1>Add Product</h1>
      {isLoggedIn ? (
        <div>
          <p>You are logged in now, you can add a product.</p>
          <form onSubmit={handleSubmit} className="add-product-form">
            <div className="form-group">
              <label htmlFor="user_id">User  ID (Pre-filled)</label>
              <input
                type="number"
                name="user_id"
                id="user_id"
                value={product.user_id}
                readOnly
              />
            </div>
            {/* Add other form fields for name, price, quantity, description, listingDate */}
            <div className="form-group">
              <label htmlFor="name">Product Name</label>
              <input
                type="text"
                name="name"
                id="name"
                value={product.name}
                onChange={handleChange}
                required
              />
            </div>
            <div className="form-group">
              <label htmlFor="price">Price</label>
              <input
                type="number"
                name="price"
                id="price"
                value={product.price}
                onChange={handleChange}
                required
              />
            </div>
            <div className="form-group">
              <label htmlFor="quantity">Quantity</label>
              <input
                type="number"
                name="quantity"
                id="quantity"
                value={product.quantity}
                onChange={handleChange}
                required
              />
            </div>
            <div className="form-group">
              <label htmlFor="description">Description</label>
              <textarea
                name="description"
                id="description"
                value={product.description}
                onChange={handleChange}
                required
              />
            </div>
            <div className="form-group">
              <label htmlFor="listingDate">Listing Date</label>
              <input
                type="date"
                name ="listingDate"
                id="listingDate"
                value={product.listingDate}
                onChange={handleChange}
                required
              />
            </div>
            <button type="submit" className="submit-button">Add Product</button>
          </form>
        </div>
      ) : (
        <p>Please log in to add a product.</p>
      )}
    </div>
  );
};

export default AddProduct;
